  if (emails.length !== 4) errors.push(`expected 4 emails, got ${emails.length}`);
  const steps = emails.map((e) => e && Number(e.step)).sort();
  if (steps.join(',') !== '1,2,3,4') errors.push('steps must be 1,2,3,4');
